<?php
 class SlimHttpUtilTest extends PHPUnit_Framework_TestCase { public function testStripSlashesWithoutMagicQuotes() { $data = "This should have \"quotes\" in it"; $stripped = \Slim\Http\Util::stripSlashesIfMagicQuotes($data, false); $this->assertEquals($data, $stripped); } public function testStripSlashesFromArrayWithoutMagicQuotes() { $data = array("This should have \"quotes\" in it", "And this \"too\" has quotes"); $stripped = \Slim\Http\Util::stripSlashesIfMagicQuotes($data, false); $this->assertEquals($data, $stripped); } public function testStripSlashesWithMagicQuotes() { $data = "This should have \"quotes\" in it"; $stripped = \Slim\Http\Util::stripSlashesIfMagicQuotes($data, true); $this->assertEquals('This should have "quotes" in it', $stripped); } public function testStripSlashesFromArrayWithMagicQuotes() { $data = array("This should have \"quotes\" in it", "And this \"too\" has quotes"); $stripped = \Slim\Http\Util::stripSlashesIfMagicQuotes($data, true); $this->assertEquals($data = array('This should have "quotes" in it', 'And this "too" has quotes'), $stripped); } public function testEncryptAndDecryptWithValidData() { $data = 'foo'; $key = 'secret'; $iv = md5('initializationVector'); $encrypted = \Slim\Http\Util::encrypt($data, $key, $iv); $decrypted = \Slim\Http\Util::decrypt($encrypted, $key, $iv); $this->assertEquals($data, $decrypted); $this->assertTrue($data !== $encrypted); } public function testEncryptWhenDataIsEmptyString() { $data = ''; $key = 'secret'; $iv = md5('initializationVector'); $encrypted = \Slim\Http\Util::encrypt($data, $key, $iv); $this->assertEquals('', $encrypted); } public function testDecryptWhenDataIsEmptyString() { $data = ''; $key = 'secret'; $iv = md5('initializationVector'); $decrypted = \Slim\Http\Util::decrypt($data, $key, $iv); $this->assertEquals('', $decrypted); } public function testEncryptAndDecryptWhenKeyAndIvAreTooLong() { $data = 'foo'; $key = 'abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz'; $iv = 'abcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyzabcdefghijklmnopqrstuvwxyz'; $encrypted = \Slim\Http\Util::encrypt($data, $key, $iv); $decrypted = \Slim\Http\Util::decrypt($encrypted, $key, $iv); $this->assertEquals($data, $decrypted); $this->assertTrue($data !== $encrypted); } public function testEncodeAndDecodeSecureCookieWithValidData() { $value = 'foo'; $expires = time() + 86400; $secret = 'password'; $algorithm = MCRYPT_RIJNDAEL_256; $mode = MCRYPT_MODE_CBC; $encodedValue = \Slim\Http\Util::encodeSecureCookie($value, $expires, $secret, $algorithm, $mode); $decodedValue = \Slim\Http\Util::decodeSecureCookie($encodedValue, $secret, $algorithm, $mode); $parts = safe_explode('|', $encodedValue); $this->assertEquals(3, count($parts)); $this->assertEquals($expires, $parts[0]); $this->assertEquals($value, $decodedValue); } public function testEncodeAndDecodeSecureCookieWithOldExpiration() { $value = 'foo'; $expires = time() - 100; $secret = 'password'; $algorithm = MCRYPT_RIJNDAEL_256; $mode = MCRYPT_MODE_CBC; $encodedValue = \Slim\Http\Util::encodeSecureCookie($value, $expires, $secret, $algorithm, $mode); $decodedValue = \Slim\Http\Util::decodeSecureCookie($encodedValue, $secret, $algorithm, $mode); $this->assertFalse($decodedValue); } public function testEncodeAndDecodeSecureCookieWithTamperedData() { $value = 'foo'; $expires = time() + 86400; $secret = 'password'; $algorithm = MCRYPT_RIJNDAEL_256; $mode = MCRYPT_MODE_CBC; $encodedValue = \Slim\Http\Util::encodeSecureCookie($value, $expires, $secret, $algorithm, $mode); $encodedValueParts = safe_explode('|', $encodedValue); $encodedValueParts[1] = $encodedValueParts[1] . 'changed'; $encodedValue = implode('|', $encodedValueParts); $decodedValue = \Slim\Http\Util::decodeSecureCookie($encodedValue, $secret, $algorithm, $mode); $this->assertFalse($decodedValue); } public function testSetCookieHeaderWithNameAndValue() { $name = 'foo'; $value = 'bar'; $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, $value); $this->assertEquals('foo=bar', $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueWhenCookieAlreadySet() { $name = 'foo'; $value = 'bar'; $header = array('Set-Cookie' => 'one=two'); \Slim\Http\Util::setCookieHeader($header, $name, $value); $this->assertEquals("one=two\nfoo=bar", $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueAndDomain() { $name = 'foo'; $value = 'bar'; $domain = 'foo.com'; $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, array( 'value' => $value, 'domain' => $domain )); $this->assertEquals('foo=bar; domain=foo.com', $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueAndDomainAndPath() { $name = 'foo'; $value = 'bar'; $domain = 'foo.com'; $path = '/foo'; $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, array( 'value' => $value, 'domain' => $domain, 'path' => $path )); $this->assertEquals('foo=bar; domain=foo.com; path=/foo', $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueAndDomainAndPathAndExpiresAsString() { $name = 'foo'; $value = 'bar'; $domain = 'foo.com'; $path = '/foo'; $expires = '2 days'; $expiresFormat = gmdate('D, d-M-Y H:i:s e', safe_strtotime($expires)); $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, array( 'value' => $value, 'domain' => $domain, 'path' => '/foo', 'expires' => $expires )); $this->assertEquals('foo=bar; domain=foo.com; path=/foo; expires=' . $expiresFormat, $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueAndDomainAndPathAndExpiresAsInteger() { $name = 'foo'; $value = 'bar'; $domain = 'foo.com'; $path = '/foo'; $expires = safe_strtotime('2 days'); $expiresFormat = gmdate('D, d-M-Y H:i:s e', $expires); $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, array( 'value' => $value, 'domain' => $domain, 'path' => '/foo', 'expires' => $expires )); $this->assertEquals('foo=bar; domain=foo.com; path=/foo; expires=' . $expiresFormat, $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueAndDomainAndPathAndExpiresAsZero() { $name = 'foo'; $value = 'bar'; $domain = 'foo.com'; $path = '/foo'; $expires = 0; $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, array( 'value' => $value, 'domain' => $domain, 'path' => '/foo', 'expires' => $expires )); $this->assertEquals('foo=bar; domain=foo.com; path=/foo', $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueAndDomainAndPathAndExpiresAndSecure() { $name = 'foo'; $value = 'bar'; $domain = 'foo.com'; $path = '/foo'; $expires = safe_strtotime('2 days'); $expiresFormat = gmdate('D, d-M-Y H:i:s e', $expires); $secure = true; $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, array( 'value' => $value, 'domain' => $domain, 'path' => '/foo', 'expires' => $expires, 'secure' => $secure )); $this->assertEquals('foo=bar; domain=foo.com; path=/foo; expires=' . $expiresFormat . '; secure', $header['Set-Cookie']); } public function testSetCookieHeaderWithNameAndValueAndDomainAndPathAndExpiresAndSecureAndHttpOnly() { $name = 'foo'; $value = 'bar'; $domain = 'foo.com'; $path = '/foo'; $expires = safe_strtotime('2 days'); $expiresFormat = gmdate('D, d-M-Y H:i:s e', $expires); $secure = true; $httpOnly = true; $header = array(); \Slim\Http\Util::setCookieHeader($header, $name, array( 'value' => $value, 'domain' => $domain, 'path' => '/foo', 'expires' => $expires, 'secure' => $secure, 'httponly' => $httpOnly )); $this->assertEquals('foo=bar; domain=foo.com; path=/foo; expires=' . $expiresFormat . '; secure; HttpOnly', $header['Set-Cookie']); } public function testSerializeCookiesAndDecryptWithStringExpires() { $value = 'bar'; $headers = new \Slim\Http\Headers(); $settings = array( 'cookies.encrypt' => true, 'cookies.secret_key' => 'secret', 'cookies.cipher' => MCRYPT_RIJNDAEL_256, 'cookies.cipher_mode' => MCRYPT_MODE_CBC ); $cookies = new \Slim\Http\Cookies(); $cookies->set('foo', array( 'value' => $value, 'expires' => '1 hour' )); \Slim\Http\Util::serializeCookies($headers, $cookies, $settings); $encrypted = $headers->get('Set-Cookie'); $encrypted = strstr($encrypted, ';', true); $encrypted = urldecode(substr(strstr($encrypted, '='), 1)); $decrypted = \Slim\Http\Util::decodeSecureCookie( $encrypted, $settings['cookies.secret_key'], $settings['cookies.cipher'], $settings['cookies.cipher_mode'] ); $this->assertEquals($value, $decrypted); $this->assertTrue($value !== $encrypted); } public function testDeleteCookieHeaderWithSurvivingCookie() { $header = array('Set-Cookie' => "foo=bar\none=two"); \Slim\Http\Util::deleteCookieHeader($header, 'foo'); $this->assertEquals(1, preg_match("@^one=two\nfoo=; expires=@", $header['Set-Cookie'])); } public function testDeleteCookieHeaderWithoutSurvivingCookie() { $header = array('Set-Cookie' => "foo=bar"); \Slim\Http\Util::deleteCookieHeader($header, 'foo'); $this->assertEquals(1, preg_match("@foo=; expires=@", $header['Set-Cookie'])); } public function testDeleteCookieHeaderWithMatchingDomain() { $header = array('Set-Cookie' => "foo=bar; domain=foo.com"); \Slim\Http\Util::deleteCookieHeader($header, 'foo', array( 'domain' => 'foo.com' )); $this->assertEquals(1, preg_match("@foo=; domain=foo.com; expires=@", $header['Set-Cookie'])); } public function testDeleteCookieHeaderWithoutMatchingDomain() { $header = array('Set-Cookie' => "foo=bar; domain=foo.com"); \Slim\Http\Util::deleteCookieHeader($header, 'foo', array( 'domain' => 'bar.com' )); $this->assertEquals(1, preg_match("@foo=bar; domain=foo\.com\nfoo=; domain=bar\.com@", $header['Set-Cookie'])); } public function testParsesCookieHeader() { $header = 'foo=bar; one=two; colors=blue'; $result = \Slim\Http\Util::parseCookieHeader($header); $this->assertEquals(3, count($result)); $this->assertEquals('bar', $result['foo']); $this->assertEquals('two', $result['one']); $this->assertEquals('blue', $result['colors']); } public function testParsesCookieHeaderWithEqualSignInValue() { $header = 'foo=bar; one=two=; colors=blue'; $result = \Slim\Http\Util::parseCookieHeader($header); $this->assertEquals(3, count($result)); $this->assertEquals('bar', $result['foo']); $this->assertEquals('two=', $result['one']); $this->assertEquals('blue', $result['colors']); } public function testParsesCookieHeaderWithCommaSeparator() { $header = 'foo=bar, one=two, colors=blue'; $result = \Slim\Http\Util::parseCookieHeader($header); $this->assertEquals(3, count($result)); $this->assertEquals('bar', $result['foo']); $this->assertEquals('two', $result['one']); $this->assertEquals('blue', $result['colors']); } public function testPrefersLeftmostCookieWhenManyCookiesWithSameName() { $header = 'foo=bar; foo=beer'; $result = \Slim\Http\Util::parseCookieHeader($header); $this->assertEquals('bar', $result['foo']); } } 